# bash completion for "PROG", generated by docopt-completion

FN() {
  "REFRESH"
  "TABLES"
  # Rejoin what COMP_WORDBREAKS split (--opt=value, host:port): pieces with no whitespace between them
  local line=${COMP_LINE:0:COMP_POINT} words=() i w
  line=${line#*"${COMP_WORDS[0]}"}
  for ((i=1; i<=COMP_CWORD; i++)); do
    w=${COMP_WORDS[i]}
    if [[ -n $w && $line = "$w"* && ${#words[@]} -gt 0 ]]; then
      words[${#words[@]}-1]+=$w
    else
      words+=("$w")
    fi
    line=${line#*"$w"}
  done
  local cur=${words[${#words[@]}-1]} piece=${COMP_WORDS[COMP_CWORD]}
  # Readline replaces only what follows the last word break, strip the rest from the replies
  for ((i=0; i<${#piece}; i++)); do
    [[ $COMP_WORDBREAKS = *"${piece:i:1}"* ]] || break
  done
  [[ $i -eq ${#piece} ]] && piece=''
  local strip=$((${#cur} - ${#piece}))
  unset 'words[${#words[@]}-1]'

  local state=0 expect=-1 positional=false used=' ' word opt pos
  for word in "${words[@]}"; do
    if [[ $state = -1 ]]; then
      return 0
    elif [[ $expect != -1 ]]; then
      expect=-1
    elif ! $positional && [[ $word = -- ]]; then
      positional=true
      state=${st_sep[state]}
    elif ! $positional && [[ $word = --* ]]; then
      if HELPERS_find "${word%%=*}" true; then
        used+="$opt "
        [[ ${opt_arg[opt]} = 1 && $word != *=* ]] && expect=$opt
      fi
    elif ! $positional && [[ $word = -?* ]]; then
      for ((pos=1; pos<${#word}; pos++)); do
        if HELPERS_find "-${word:pos:1}" false; then
          used+="$opt "
          if [[ ${opt_arg[opt]} = 1 ]]; then
            [[ $pos -eq $((${#word}-1)) ]] && expect=$opt
            break
          fi
        fi
      done
    else
      pos=${st_other[state]}
      for i in "${!cmd_state[@]}"; do
        if [[ ${cmd_state[i]} = "$state" && ${cmd_name[i]} = "$word" ]]; then
          pos=${cmd_next[i]}
          break
        fi
      done
      state=$pos
    fi
  done
  [[ $state = -1 ]] && return 0

  local items=() values=() src=-1 prefix=''
  if [[ $expect != -1 ]]; then
    src=${opt_src[expect]}
  elif ! $positional && [[ $cur = --*=* ]]; then
    HELPERS_find "${cur%%=*}" true && [[ ${opt_arg[opt]} = 1 ]] || return 0
    src=${opt_src[opt]}
    prefix=${cur%%=*}=
  else
    local options=() commands=()
    if ! $positional; then
      for i in ${st_opts[state]}; do
        # shellcheck disable=SC2206
        [[ $used = *" $i "* && ${opt_rep[i]} = 0 ]] || options+=(${opt_names[i]})
      done
    fi
    for i in "${!cmd_state[@]}"; do
      [[ ${cmd_state[i]} = "$state" ]] && commands+=("${cmd_name[i]}")
    done
    if ! $positional && [[ $cur = -* ]]; then
      items=("${options[@]}")
    elif [[ ${#commands[@]} -eq 0 && ${st_other[state]} = -1 ]]; then
      items=("${options[@]}")
    else
      items=("${commands[@]}")
      src=${st_src[state]}
    fi
  fi
  for w in "${items[@]}"; do
    [[ $w = "$cur"* ]] && COMPREPLY+=("${w:strip}")
  done
  [[ $src = -1 ]] && return 0
  HELPERS_source "$src" "${cur#"$prefix"}"
  for w in "${values[@]}"; do
    w=$prefix$w
    COMPREPLY+=("${w:strip}")
  done
}

# Sets $opt to the option named $1, matching long options by prefix when $2 is true
HELPERS_find() {
  local i n matches=() first=''
  for i in "${!opt_names[@]}"; do
    for n in ${opt_names[i]}; do
      [[ $n = "$1" ]] && matches+=("$i")
    done
  done
  if [[ ${#matches[@]} -eq 0 && $2 = true ]]; then
    for i in "${!opt_names[@]}"; do
      n=${opt_names[i]%% *}
      if [[ $n = "$1"* ]]; then
        [[ -n $first && $first != "$n" ]] && return 1
        first=$n
        matches+=("$i")
      fi
    done
  fi
  [[ ${#matches[@]} -gt 0 ]] || return 1
  opt=${matches[0]}
  for i in "${matches[@]}"; do
    if [[ " ${st_opts[state]} " = *" $i "* ]]; then
      opt=$i
      return 0
    fi
  done
}

# Adds the candidates of source set $1 that start with $2 to $values
HELPERS_source() {
  local w
  case $1 in
    "SOURCES"
  esac
}

complete -F FN "PROG"
